export class DaprConfigModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class DaprConfigService implements OnModuleInit {
  private readonly context: JobsLogContext = {
    method: '',
    service: DaprConfigService.name,
  };

  public constructor(
    private readonly configService: ConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get plantHierarchyApiAppId(): string {
    return this.configService.get<string>('plantHierarchyApiAppId') ?? '';
  }

  public onModuleInit(): void {
    this.checkConfiguration();
