    const context = DaprServiceApi.createLogContext('initializePlant');
    try {
      this.plantList = await getListPlant(
        this.customLogger,
        this.daprClient,
        this.subscribeMessageService,
        this.redisConfigService.redisStore,
        this.redisConfigService.redisPlantKey,
      );
      this.customLogger.log(
        `Updated Plants List: ${JSON.stringify(this.plantList)}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to get plant list: ${error.message}`,
        context,
        error,
      );
    }
  }

  /**
   * Update data without using cache if there's no result from Redis,
   * and after confirming whether the data is inserted or not.
   * @param keysValueArray - Array of key-value pairs
   * @param mappedData - The mapped data
   * @param operation - The operation type (e.g., 'u' for update)
   * @returns - Returns true if data is updated, false otherwise
   */
  private async updateDataWithoutCache(
    keysValueArray: KeysValueArray,
    mappedData: MappedOutput,
    operation: string,
  ): Promise<boolean> {
    // This is a custom situation in the case of orders. In other cases, we can use EventEmitter to dynamically adjust the function.
    const operationInfo = {
      name: '',
      srcLocation: 'updateDataWitoutCache',
    };
    const context = DaprServiceApi.createLogContext(
      'updateDataWithoutCache',
      mappedData?.plant,
      JSON.stringify(keysValueArray),
    );
    operationInfo.name = 'Find Order and Source Table (SQL)';
    const resultOrder = await execAndLog(
      this.customLogger,
      context,
      () => this.orderService.findOrder(keysValueArray),
      operationInfo,
      { keysValueArray },
    );

    this.customLogger.debug(
      `Received from find Order -  result: ${JSON.stringify(resultOrder)}`,
      context,
    );

    // ð Early return to reduce nesting
    if (!resultOrder) {
      return false;
    }

    const data = {
      ...mappedData,
      [resultOrder.pickingOrderId ? 'pickingOrderId' : 'productionOrderId']:
        resultOrder.pickingOrderId ?? resultOrder.productionOrderId,
    };

    await emitSqlEvent(
      this.customLogger,
      context,
      this.eventEmitter,
      resultOrder.source_table,
      data,
      operation,
    );

    return true;
  }

  /**
   * Process the message
   * @param message Mapped Data to process
   * @param redisStore redisStore
   */
  private async processMessage(
    message: RedisMessage,
    redisStore: string,
  ): Promise<void> {
    const {
      mappedData,
      destination,
      operation,
      keysValueArray,
      cacheTreatment,
      ingestionEventTracking,
    } = message;
    const plant = mappedData?.plant;
    const context = DaprServiceApi.createLogContext(
      'processMessage',
      mappedData?.plant,
    );
    try {
      if (!operation || !keysValueArray) {
        return;
      }
      if (operation !== 'r' && ingestionEventTracking) {
        const validateAndTrackIngestionEventTracking: boolean =
          await validateAndTrackChanges(
            this.customLogger,
            this.ingestionEventTrackingService,
            ingestionEventTracking,
          );
        if (!validateAndTrackIngestionEventTracking) {
          return;
        }
        await this.ingestionEventTrackingService.upsertCache(
          ingestionEventTracking,
        );
      }
      await (cacheTreatment
        ? this.aggregatorService.processWithAggregation(
            plant,
            message,
            keysValueArray,
            redisStore,
          )
        : emitSqlEvent(
            this.customLogger,
            context,
            this.eventEmitter,
            destination,
            mappedData,
            operation,
          ));
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
      );
    }
  }

  /**
   * Process the message with Cache Processing Logic
   * @param plant Plant Id
   * @param message Redis Message,
   * @param keysValueArray Keys Value Array,
   * @param redisStore redisStore
   */
  public async processMessageWithCache(
    plant: number,
    message: RedisMessage,
    keysValueArray: KeysValueArray,
    redisStore: string,
  ): Promise<void> {
    const context = DaprServiceApi.createLogContext(
      'processMessageWithCache',
      plant,
    );
    const { mappedData, keysValue, destination, sourceTable, operation } =
      message;

    const cacheKey = `${keysValue}.${operation}`;
    const operationInfo = {
      name: '',
      srcLocation: 'processMessage',
    };
    const operationDetails = {
      cacheKey,
      plant,
    };
    try {
      this.customLogger.debug(`Checking state key: ${cacheKey}`, context);
      operationInfo.name = 'Get state';
      const result = await execAndLog(
        this.customLogger,
        context,
        () => this.daprClient.state.get(redisStore, cacheKey),
        operationInfo,
        operationDetails,
      );

      // Update data without using cache if there's no result from Redis,
      // And after confirming whether the data is inserted or not.
      if (!result.valueOf() && operation === 'u') {
        operationInfo.name = 'UpdateDataWithoutCache';
        const dataUpdated = await execAndLog(
          this.customLogger,
          context,
          () =>
            this.updateDataWithoutCache(keysValueArray, mappedData, operation),
          operationInfo,
          { keysValueArray },
        );
        if (dataUpdated) {
          return;
        }
      }

      // Caching the first wave of data
      if (
        !result.valueOf() ||
        Object.values(result.valueOf())[0].sourceTable === sourceTable
      ) {
        if (!sourceTable) {
          return;
        }

        const recordCache = {
          destination,
          keysValue,
          mappedData,
          sourceTable,
        };
        await appendAndSaveToCache(
          this.customLogger,
          this.daprClient,
          this.redisConfigService.redisStore,
          cacheKey,
          result,
          recordCache,
        );
        return;
      }
      const redisData = Object.values(result.valueOf()).at(-1).mappedData;
      const destinationRedis = Object.values(result.valueOf()).at(
        -1,
      ).destination;

      const destinationService = destinationRedis + destination;
      const completedData = { ...redisData, ...mappedData }; // Append the data
      // Unstack the oldest records (FIFO logic)

      operationInfo.name = 'Delete state';
      await execAndLog(
        this.customLogger,
        context,
        async () => {
          // We processed the last records => Cache can be freed
          this.customLogger.debug(`Deleting state key: ${cacheKey}`, context);
          return this.daprClient.state.delete(redisStore, cacheKey);
        },
        operationInfo,
        operationDetails,
      );
      if (!operation) {
        return;
      }
      await emitSqlEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        destinationService,
        completedData,
        operation,
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
        error.stack,
      );
    } finally {
      this.customLogger.debug(
        `End of processing message for ${cacheKey} at ${Date.now()} `,
        context,
      );
    }
  }

  public async handleMessageRedis(message: {
    id: string;
    message: {
      [x: string]: string;
    };
  }): Promise<void> {
    const context = DaprServiceApi.createLogContext('handleMessageRedis');
    this.customLogger.debug(
      `Received Redis Message - payload: ${JSON.stringify(message)}`,
      context,
    );

    try {
      // Extract the payload from message.message.payload
      const payloadString = message.message.payload;

      if (!payloadString) {
        this.customLogger.warn('No payload found in Redis message', context);
        return;
      }

      // Parse the payload JSON string
      const payload = JSON.parse(payloadString) as CombinedDtoWithIndex;

      this.customLogger.debug(
        `Parsed payload: ${JSON.stringify(payload)}`,
        context,
      );

      // Execute both operations in parallel
      const promises: Array<Promise<void>> = [this.handleMessage(payload)];

      // Add buffered message handling if source table is S_PICKING_ORDER
      if (payload.__source_table === 'S_PICKING_ORDER') {
        const bufferedMessage = {
          ...payload,
          __source_table: 'buffer',
        };
        promises.push(this.handleMessage(bufferedMessage));
      }

      // Wait for all promises to complete in parallel
      await Promise.all(promises);
    } catch (error) {
      this.customLogger.error(
        `Error processing Redis message: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  /**
   * Message handler
   * @param record Record To handle
   */
  public async handleMessage(record: CombinedDtoWithIndex): Promise<void> {
    const context = DaprServiceApi.createLogContext('handleMessage');
    this.customLogger.debug(
      `Received - payload: ${JSON.stringify(record)}`,
      context,
    );
    incrementPendingMessageCount();
    const dateStart = Date.now();
    const shopOrder = record.SHOP_ORDER ?? record.S_SHOP_ORDER ?? 'unknown';
    const operationInfo = {
      name: '',
      srcLocation: 'handleMessage',
    };
    const operationDetails = {
      shopOrder,
    };

    try {
      const { __source_table: sourceTable, __op: operation } = record;
      this.customLogger.debug(
        `Received - operation: ${operation} - payload: ${JSON.stringify(record)}`,
        context,
      );
      if (!sourceTable) return;
      const {
        mappedData,
        destination,
        ingestionEventTracking,
        keysValue,
        keysValueArray,
        cacheTreatment,
      } = this.mappingService.mapData(sourceTable, record, this.plantList);
      // Check first if there is two table source in the mapping system
      // Fifo check
      this.customLogger.debug(
        `Mapped Data:${JSON.stringify(mappedData)}`,
        context,
      );
      const newRecord = {
        cacheTreatment,
        destination,
        ingestionEventTracking,
        keysValue,
        keysValueArray,
        mappedData,
        operation,
        sourceTable,
      };
      await this.processMessage(newRecord, this.redisConfigService.redisStore);
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.stack ?? error.message ?? JSON.stringify(error)}`,
        context,
      );
    } finally {
      if (record) {
        operationInfo.name = 'handleMessage function runtime';
        await execAndLog(
          this.customLogger,
          context,
          async () => {},
          operationInfo,
          operationDetails,
          dateStart,
        );
      }
      decrementPendingMessageCount();
    }
  }
}

